// ============================================================
// ICE LOGIX: Review Platform Original PNG Data URIs
// Stored in RAM for 0ms Instant Zero-Flicker Rendering
// ============================================================
window.REVIEWS_PLATFORM_LOGOS = {
  "yandex-maps": "data:image/png;base64,",
  "google-maps": "data:image/png;base64,",
  "2gis": "data:image/png;base64,",
  "telegram": "data:image/png;base64,",
  "vk": "data:image/png;base64,",
  "threads": "data:image/png;base64,",
  "instagram": "data:image/png;base64,",
  "facebook": "data:image/png;base64,",
};

// Pre-warm review platform images in browser memory immediately
if (typeof window !== "undefined") {
  Object.values(window.REVIEWS_PLATFORM_LOGOS).forEach(function(src) {
    try {
      var img = new Image();
      img.decoding = "sync";
      img.src = src;
    } catch(e) {}
  });
}
